-- Name: Overlapping BP DP Throughput - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM (VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815),(247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517),(300439),(265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142),(636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528),(94782),(77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705),(1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489),(747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983),(81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219),(134),(94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475),(74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351),(960),(70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534),(77093),(154),(1001),(70030),(576),(70429),(217),(196420),(205655)) AS x(dest_id) ), srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.os, s.channel, date_format(at_timezone(s.__time, 'Asia/Kolkata'), '%Y-%b') AS month_period FROM "user_interaction"."search_route_details" s -- JOIN piligrim_dest_list p ON p.dest_id = s.dest_id WHERE s.__time >= TIMESTAMP '2026-03-23 18:30:00' AND s.__time < TIMESTAMP '2026-04-05 18:30:00' AND s.os = 'Android' AND s.country = 'IND' ), ui_session_flags AS ( SELECT mri_session_id, -- Scenario A: Boarding Point Screen MAX (CASE WHEN event_name = 'BP DP screen loaded' THEN 1 ELSE 0 END) AS bp_dp_screen_loaded, MAX(CASE WHEN screen_name = 'boarding point screen' AND event_name = 'alternate_bp_shown' AND event_value = 'Yes' THEN 1 ELSE 0 END) as alt_bp_shown, MAX(CASE WHEN screen_name = 'boarding point screen' AND event_name = 'alternate_bp_selected' AND event_value = 'Yes' THEN 1 ELSE 0 END) as alt_bp_selected, -- Scenario B: Dropping Point Screen MAX(CASE WHEN screen_name = 'dropping point screen' AND event_name = 'alternate_bp_shown' AND event_value = 'Yes' THEN 1 ELSE 0 END) as alt_dp_shown, MAX(CASE WHEN screen_name = 'dropping point screen' AND event_name = 'alternate_Dp_selected' AND event_value = 'Yes' THEN 1 ELSE 0 END) as alt_dp_selected, -- Scenario C: Cust Info MAX(CASE WHEN screen_name = 'Cust Info Screen' AND event_name = 'CI_with_alternateBP' AND event_value = 'Yes' THEN 1 ELSE 0 END) as ci_alt_bp, -- Scenario D: SL Load MAX(CASE WHEN screen_name = 'sl load' AND event_name = 'alternatebpshown_clickedback' AND event_value = 'Yes' THEN 1 ELSE 0 END) as alt_bp_clickedback FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-03-23 18:30:00' AND __time < TIMESTAMP '2026-04-05 18:30:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' GROUP BY 1 ), sl_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-03-23 18:30:00' AND __time < TIMESTAMP '2026-04-05 18:30:00' AND country = 'IND' GROUP BY 1,2\ ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-03-23 18:30:00' AND __time < TIMESTAMP '2026-04-05 18:30:00' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-03-23 18:30:00' AND __time < TIMESTAMP '2026-04-05 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- srp.month_period, 'Mar 24 to Apr 05' AS month_period, COALESCE(srp.os, srp.channel) AS saleschannel, -- Tagging the Variations CASE WHEN u.bp_dp_screen_loaded = 1 THEN 'Yes' ELSE 'No' END AS bp_dp_screen_loaded, CASE WHEN u.alt_bp_shown = 1 THEN 'Yes' ELSE 'No' END AS Alt_BP_Shown, CASE WHEN u.alt_bp_selected = 1 THEN 'Yes' ELSE 'No' END AS Alt_BP_Selected, -- CASE WHEN u.alt_dp_shown = 1 THEN 'Yes' ELSE 'No' END AS Alt_DP_Shown, -- CASE WHEN u.alt_dp_selected = 1 THEN 'Yes' ELSE 'No' END AS Alt_DP_Selected, -- CASE WHEN u.ci_alt_bp = 1 THEN 'Yes' ELSE 'No' END AS CI_with_AltBP, -- CASE WHEN u.alt_bp_clickedback = 1 THEN 'Yes' ELSE 'No' END AS AltBP_ClickedBack, -- Funnel Metrics COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS paxload, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, SUM(conf.tin_count) AS tin FROM srp_deduped srp INNER JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN ui_session_flags u ON srp.mri_session_id = u.mri_session_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1, 2, 3, 4 , 5 -- , 5, 6, 7, 8 ORDER BY 3 DESC, 5 DESC, 4 DESC -- , 6 DESC, 7 DESC, 8 DESC
